//! Real filesystem AssetServer/AudioLoader -> decoded PCM Sources and World.
//! No AudioPlugin, device, sink, audible or native UI claim.
use super::*;
use bevy::audio::{AudioSource,Decodable};
use crate::resources::{VnState,VnEngine};
const GAME:&str=include_str!("../../../fixtures/game-audio-seven.rvn");
const PRE_SCENE:&str=include_str!("../../../fixtures/pre-scene-game-audio.rvn");
fn audio_fixture(source:&str,execute:bool,language:&str)->(Fixture,rvn_parser::ParsedProgram){
 let(mut f,_,_,_)=atomic_save_fixture();
 for(path,bytes)in [("music/host.wav",include_bytes!("../../../fixtures/pcm/host.wav").as_slice()),("sfx/host.wav",include_bytes!("../../../fixtures/pcm/host.wav").as_slice()),("voice/voice.wav",include_bytes!("../../../fixtures/pcm/voice.wav").as_slice())]{let p=f.root.join("assets").join(path);fs::create_dir_all(p.parent().unwrap()).unwrap();fs::write(p,bytes).unwrap();}
 f.app.init_asset::<AudioSource>().init_asset_loader::<bevy::audio::AudioLoader>().init_asset::<crate::checkpoint_pcm::CheckpointPcm>();
 f.app.init_resource::<crate::resources::ScriptErrorMessage>().init_resource::<crate::resources::MusicEntity>().init_resource::<crate::resources::MusicAssetRegistry>().init_resource::<crate::resources::MusicPlaybackState>().init_resource::<crate::resources::MusicVolume>().init_resource::<crate::resources::VnRenderState>().init_resource::<crate::resources::ChoiceFocus>().init_resource::<crate::resources::ImagemapState>().init_resource::<crate::resources::TypewriterState>().init_resource::<crate::accessibility::Accessibility>().insert_resource(State::new(VnState::Waiting)).init_resource::<NextState<VnState>>().init_resource::<crate::scene_audio::AudioFeedbackQueue>().add_event::<crate::vn_command::PlayerInput>();
 f.app.add_plugins(crate::scene_audio::SceneAudioPlugin);
 let file=f.root.join("audio.rvn");fs::write(&file,source).unwrap();let program=rvn_parser::parse_file_program_with_uses(&file).unwrap();let old=&f.app.world().resource::<VnEngine>().0;let mut locale=old.locale.as_ref().unwrap().clone();locale.set_language(language).unwrap();let mut game=Engine::from_program_with_persistent_and_text_context(program.clone(),BevyRenderer::new(),16,HashMap::new(),rvn_core::TextRuntimeContext::new(old.text_resources().clone(),Some(locale))).unwrap();if execute{game.step_until_interaction().unwrap();}f.app.world_mut().insert_resource(VnEngine(game));f.app.world_mut().resource_mut::<crate::systems::settings_menu::Settings>().language=language.into();if execute{settle(&mut f);} (f,program)
}
fn settle(f:&mut Fixture){let deadline=Instant::now()+Duration::from_secs(15);loop{f.app.update();crate::scene_publication::consume(f.app.world_mut());let engine=&f.app.world().resource::<VnEngine>().0;assert!(!engine.renderer.scene_frame_failed,"{}",f.app.world().resource::<crate::resources::ScriptErrorMessage>().0);if !engine.renderer.scene_batch_pending(){break;}assert!(Instant::now()<deadline,"Real filesystem AudioLoader did not settle");std::thread::yield_now();}f.app.world_mut().resource_mut::<Events<VnCommand>>().clear();}
fn advance(f:&mut Fixture){f.app.world_mut().resource_mut::<VnEngine>().0.advance_dialogue().unwrap();settle(f);f.app.world_mut().resource_mut::<VnEngine>().0.step_until_interaction().unwrap();settle(f);}
fn reader(world:&World,target:&rvn_core::scene_resources::TargetIdentity)->crate::checkpoint_pcm::CheckpointPcm{crate::checkpoint_sources::one_shot_source(world,target).unwrap().0}
fn cursor(reader:&crate::checkpoint_pcm::CheckpointPcm)->rvn_core::audio_checkpoint::AudioCheckpoint{reader.gate().snapshot(&[reader],|mut rows|Ok(rows.remove(0))).unwrap()}
fn full(world:&World)->String{let e=&world.resource::<VnEngine>().0;format!("{:?}|{:?}|{}|{}|{:?}|{:?}|{}",e.state,e.history.entries(),e.runtime_epoch(),world.entities().len(),e.renderer.pending,e.renderer.scene_batch,e.instance_id())}
fn targets(world:&World)->Vec<rvn_core::scene_resources::TargetIdentity>{world.resource::<VnEngine>().0.state.audio_resource_registry().unwrap().targets.iter().map(|t|t.identity.clone()).collect()}
#[test]fn actual_filesystem_sources_game_without_scene_run_seven_commands_and_retain_exact_readers(){let(mut f,_)=audio_fixture(GAME,true,"en");assert!(f.app.world().resource::<VnEngine>().0.state.scene_execution.is_none());assert!(f.app.world().resource::<VnEngine>().0.state.game_audio.is_some());let music=targets(f.app.world()).remove(0);let original=reader(f.app.world(),&music);let mut samples=original.decoder();assert!(samples.next().is_some());advance(&mut f);assert_eq!(f.app.world().resource::<VnEngine>().0.state.music.volume,0.3);assert!(reader(f.app.world(),&music).same_reader(&original));advance(&mut f);advance(&mut f);assert_eq!(f.app.world().resource::<VnEngine>().0.audio_playback_views().unwrap().len(),2);advance(&mut f);f.app.world_mut().resource_mut::<VnEngine>().0.tick_game_frame(2.0,Default::default()).unwrap();settle(&mut f);assert_eq!(f.app.world().resource::<VnEngine>().0.audio_playback_views().unwrap().len(),1);advance(&mut f);assert!(f.app.world().resource::<VnEngine>().0.audio_playback_views().unwrap().is_empty());advance(&mut f);f.app.world_mut().resource_mut::<VnEngine>().0.tick_game_frame(2.0,Default::default()).unwrap();settle(&mut f);assert!(f.app.world().resource::<VnEngine>().0.state.music.current_file.is_none());assert_eq!(samples.next(),None);}
#[test]fn pre_scene_game_music_voice_remain_visible_through_real_scene_entry_and_all_story_capture(){let(mut f,p)=audio_fixture(PRE_SCENE,true,"en");let e=&f.app.world().resource::<VnEngine>().0;assert!(e.state.game_audio.is_none());assert!(e.state.scene_execution.as_ref().unwrap().active.is_none());let before=targets(f.app.world());assert_eq!(before.len(),2);let readers=before.iter().map(|t|reader(f.app.world(),t)).collect::<Vec<_>>();let mut decoders=readers.iter().map(Decodable::decoder).collect::<Vec<_>>();for d in &mut decoders{for _ in 0..7{assert!(d.next().is_some());}}advance(&mut f);let e=&f.app.world().resource::<VnEngine>().0;assert!(e.state.scene_execution.as_ref().unwrap().active.is_some());assert!(e.state.game_audio.is_none());for(t,r)in before.iter().zip(&readers){assert!(reader(f.app.world(),t).same_reader(r));assert_eq!(cursor(r).next_sample,7);}advance(&mut f);assert_eq!(targets(f.app.world()).len(),3);let save=f.app.world().resource::<VnEngine>().0.capture_save15(&p,None,71,"Game plus Scene Sources".into()).unwrap();let state=f.app.world().resource::<VnEngine>().0.save15_state_for_audio_warming(&p,&save).unwrap();rvn_core::audio_checkpoint::require_saved_checkpoints(&state).unwrap();assert_eq!(rvn_core::audio_playback::describe(&state,0).unwrap().len(),2);assert_eq!(rvn_core::audio_checkpoint::music_views(&state,0).unwrap().len(),1);}
fn cold_actual(source:&str,advances:usize,scene:bool){let(mut warm,p)=audio_fixture(source,true,"fr");for _ in 0..advances{advance(&mut warm);}let ids=targets(warm.app.world());assert_eq!(ids.len(),3);let warm_readers=ids.iter().map(|t|reader(warm.app.world(),t)).collect::<Vec<_>>();let mut decoders=warm_readers.iter().map(Decodable::decoder).collect::<Vec<_>>();for d in &mut decoders{for _ in 0..7{assert!(d.next().is_some());}}let e=&warm.app.world().resource::<VnEngine>().0;let saved_random=e.state.random;let save=e.capture_save15(&p,None,72,"Actual Game PCM".into()).unwrap();let bytes=save.encode().unwrap();let(mut cold,_)=audio_fixture(source,false,"en");let old=&cold.app.world().resource::<VnEngine>().0;let game=Engine::from_program_with_persistent_and_text_context(p.clone(),BevyRenderer::new(),16,HashMap::new(),rvn_core::TextRuntimeContext::new(old.text_resources().clone(),old.locale.clone())).unwrap();assert_ne!(game.instance_id(),e.instance_id());cold.app.world_mut().insert_resource(VnEngine(game));let mut expected=portable_receipt(cold.app.world()).unwrap();expected.locales=save.locale.clone().unwrap();let before=full(cold.app.world());let first=crate::atomic_text_restore::prepare(cold.app.world(),&p,rvn_core::save::consumer_checkpoint::Save15::decode(&bytes).unwrap(),&expected);assert!(matches!(first,Err(ref error)if error.contains("still loading")));assert_eq!(full(cold.app.world()),before);let deadline=Instant::now()+Duration::from_secs(15);let plan=loop{cold.app.update();match crate::atomic_text_restore::prepare(cold.app.world(),&p,rvn_core::save::consumer_checkpoint::Save15::decode(&bytes).unwrap(),&expected){Ok(plan)=>break plan,Err(error)if error.contains("still loading")=>{},Err(error)=>panic!("Actual cold Game Source preflight: {error}")}assert!(Instant::now()<deadline);std::thread::yield_now();};crate::atomic_text_restore::commit(cold.app.world_mut(),plan).unwrap();let e=&cold.app.world().resource::<VnEngine>().0;assert_eq!(e.state.random,saved_random);assert_eq!(e.state.scene_execution.is_some(),scene);assert!(!e.renderer.scene_batch_pending());for((target,_),warm_decoder)in ids.iter().zip(&warm_readers).zip(&mut decoders){let restored=reader(cold.app.world(),target);let cp=cursor(&restored);assert_eq!((cp.next_sample,cp.next_channel),(7,1));let mut actual=restored.decoder();assert_eq!(actual.next(),Some(0));for _ in 0..5{assert_eq!(actual.next(),warm_decoder.next());}}}
#[test]fn cold_new_world_game_and_mixed_story_restore_all_real_pcm_cursors_and_rng_before_return(){cold_actual(GAME,3,false);cold_actual(PRE_SCENE,2,true);}

#[test]fn game_world_rollback_uses_real_retained_source_and_same_fence_before_install(){let source=r#"flow.consume_v2("audio","play"){sfx.play("host.wav")}
"Prelude"
"First"
flow.consume_v2("audio","volume"){music.volume("0.4")}
"second""#;let(mut f,_)=audio_fixture(source,true,"en");let target=targets(f.app.world()).remove(0);let original=reader(f.app.world(),&target);let mut old_decoder=original.decoder();for _ in 0..7{old_decoder.next().unwrap();}advance(&mut f);advance(&mut f);let source=f.app.world().resource::<VnEngine>().0.preview_game_audio_rollback_source().unwrap().unwrap();let before=full(f.app.world());let plan=crate::audio_rollback_restore::prepare(f.app.world(),&source).unwrap().unwrap();assert_eq!(full(f.app.world()),before);crate::audio_rollback_restore::commit(f.app.world_mut(),plan).unwrap();let actual=reader(f.app.world(),&target);assert!(!actual.same_reader(&original));assert_eq!(cursor(&actual).next_sample,7);assert_eq!(old_decoder.next(),None);assert_eq!(f.app.world().resource::<VnEngine>().0.state.music.volume,1.0);}

#[test]fn changed_real_asset_after_world_rollback_prepare_refuses_without_history_or_reader_mutation(){let source=r#"flow.consume_v2("audio","play"){sfx.play("host.wav")}
"Prelude"
"First"
flow.consume_v2("audio","volume"){music.volume("0.4")}
"second""#;let(mut f,_)=audio_fixture(source,true,"en");let target=targets(f.app.world()).remove(0);let old=reader(f.app.world(),&target);let mut decoder=old.decoder();for _ in 0..7{decoder.next().unwrap();}advance(&mut f);advance(&mut f);let source=f.app.world().resource::<VnEngine>().0.preview_game_audio_rollback_source().unwrap().unwrap();let plan=crate::audio_rollback_restore::prepare(f.app.world(),&source).unwrap().unwrap();let handle=f.app.world().resource::<AssetServer>().get_handle::<AudioSource>("sfx/host.wav").unwrap();f.app.world_mut().resource_mut::<Assets<AudioSource>>().get_mut(handle.id()).unwrap().bytes=std::sync::Arc::from(b"changed actual Wave source".to_vec());let before=full(f.app.world());let old_cursor=cursor(&old);assert!(crate::audio_rollback_restore::commit(f.app.world_mut(),plan).is_err());assert_eq!(full(f.app.world()),before);assert_eq!(cursor(&old),old_cursor);assert!(decoder.next().is_some());}
fn executed_scene(source:&str)->(Fixture,rvn_parser::ParsedProgram){let(mut f,p)=audio_fixture(source,false,"en");f.app.world_mut().resource_mut::<VnEngine>().0.step().unwrap();settle(&mut f);(f,p)}
#[test]fn partial_dialogue_rollback_accepts_the_precomputed_future_source_and_preserves_reveal(){let source=r#"scene label start
flow.consume_v2("audio","play"){sfx.play("host.wav")}
"Prelude"
"First"
flow.consume_v2("audio","volume"){music.volume("0.4")}
"Second""#;let(mut f,_)=executed_scene(source);let target=targets(f.app.world()).remove(0);let old=reader(f.app.world(),&target);let mut decoder=old.decoder();for _ in 0..7{decoder.next().unwrap();}let e=&f.app.world().resource::<VnEngine>().0;let old_display=e.display_reveal_source().unwrap();let rvn_core::Interaction::Dialogue{text,..}=e.displayed_interaction().unwrap().unwrap()else{panic!("actual dialogue")};let reveal=rvn_core::display_reveal::RevealCheckpoint::observed(&text,2,true,0.125,0.375).unwrap();f.app.world_mut().resource_mut::<VnEngine>().0.record_display_reveal(&old_display,reveal.clone()).unwrap();{let mut e=f.app.world_mut().resource_mut::<VnEngine>();let mut session=e.0.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![]).unwrap();for _ in 0..32{if e.0.debug_step(&mut session,rvn_core::editor_debugger::StepKind::Continue).unwrap().0==rvn_core::engine::DebugProgress::Complete{break;}}}settle(&mut f);let source=f.app.world().resource::<VnEngine>().0.preview_game_audio_rollback_source().unwrap().unwrap();let plan=crate::audio_rollback_restore::prepare(f.app.world(),&source).unwrap().unwrap();let future=plan.future_display_source().expect("future source from prepared Core, not recalculated after commit");crate::audio_rollback_restore::commit(f.app.world_mut(),plan).unwrap();let e=&f.app.world().resource::<VnEngine>().0;assert!(e.accepts_display_reveal_source(&future));assert!(!e.accepts_display_reveal_source(&old_display));assert_eq!(e.state.scene_execution.as_ref().unwrap().display.as_ref().unwrap().reveal.as_ref(),Some(&reveal));}
#[test]fn choice_rollback_backdrop_uses_the_frozen_visit_not_changed_current_variables(){let source=r#"init{set value=1}
scene label start
flow.consume_v2("audio","play"){sfx.play("host.wav")}
"Value [value]"
choice {"select"=>{set value=2 jump next}}
label next
"Later""#;let(mut f,_)=executed_scene(source);f.app.world_mut().resource_mut::<VnEngine>().0.step().unwrap();settle(&mut f);f.app.world_mut().resource_mut::<VnEngine>().0.step_silent().unwrap();settle(&mut f);assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["value"],rvn_parser::Value::Int(2));let source=f.app.world().resource::<VnEngine>().0.preview_game_audio_rollback_source().unwrap().unwrap();let plan=crate::audio_rollback_restore::prepare(f.app.world(),&source).unwrap().unwrap();let expected=Some(rvn_core::Interaction::Dialogue{character:None,text:"Value 1".into()});assert_eq!(plan.future_choice_backdrop(),expected);crate::audio_rollback_restore::commit(f.app.world_mut(),plan).unwrap();assert!(matches!(f.app.world().resource::<VnEngine>().0.displayed_interaction().unwrap(),Some(rvn_core::Interaction::Choice{..})));let expected=crate::systems::dialogue::prepare_choice_backdrop_from_interaction(expected).unwrap();assert!(!crate::systems::dialogue::choice_backdrop_changed(f.app.world(),&expected));}
#[test]fn existing_app_game_frame_gates_control_game_audio_without_granting_host_authority(){let(mut f,_)=audio_fixture(GAME,true,"en");f.app.add_plugins(crate::scene_publication::ScenePublicationPlugin);let before=f.app.world().resource::<VnEngine>().0.state.random;assert!(!crate::scene_publication::host_clock_allowed(f.app.world().resource::<VnEngine>(),true,false));f.app.world_mut().insert_resource(State::new(VnState::Menu));let state=serde_json::to_value(&f.app.world().resource::<VnEngine>().0.state).unwrap();f.app.world_mut().resource_mut::<Time>().advance_by(Duration::from_millis(125));f.app.world_mut().run_schedule(Update);assert_eq!(serde_json::to_value(&f.app.world().resource::<VnEngine>().0.state).unwrap(),state);f.app.world_mut().insert_resource(State::new(VnState::Waiting));f.app.world_mut().resource_mut::<Time>().advance_by(Duration::from_millis(125));f.app.world_mut().run_schedule(Update);let e=&f.app.world().resource::<VnEngine>().0;assert_eq!(e.state.random,before);assert!(e.state.audio_resource_registry().unwrap().tasks.iter().filter_map(|t|t.effect.as_ref()).any(|effect|effect.clock.elapsed>0.0));}
